mapper.insert:
INSERT INTO users (
    name,
    status
) VALUES (
    #{name},
    #{status}
)
RETURNING id, name, status, created_at

mapper.update:
UPDATE users
SET name = #{name}
WHERE id = #{id}
RETURNING id, name, status, created_at

UPDATE users SET status = 'disabled' WHERE id IN
#{id}
RETURNING id, name, status, created_at

mapper.delete:
DELETE FROM users
WHERE id = #{id}
RETURNING id, name, status, created_at

mapper.select:
SELECT id, name, status, created_at
FROM users
WHERE id = #{id}

SELECT id, name, status, created_at
FROM users
WHERE status = #{status}
